/**
 * Goal ring (G8a, spec/02 §3.7): 112 dp times sbTextScale(), one arc per unit (1 to 12; above 12 use a share row) on a 48 dp radius with
 * 9° gaps, clockwise from twelve o'clock; [done] parts in text 8 dp, open parts in borderStrong 2 dp, butt caps. In
 * the middle the count in title over „von 8“ in caption textMuted, then [caption] under the ring; [reached] adds
 * SbStatus(Success, „erreicht“) below (no green in the ring). Not a button and not the loading ring. One TalkBack
 * node; when reached, „erreicht“ is its state (SbStatus merges on its own, so it would be a second stop: hidden here).
 */
@Composable
fun SbGoalRing(
    done: Int,
    total: Int,
    caption: String,
    modifier: Modifier = Modifier,
    reached: Boolean = done >= total,
) {
    require(total in 1..12) { "SbGoalRing: 1 to 12 units (G8a); above 12 use SbShareRows" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val numeric = ty.numeric.fontFeatureSettings
    val rem = sbTextScale()   // the web's ring is 7rem: it grows with the text inside it
    Column(
        modifier.semantics(mergeDescendants = true) { if (reached) stateDescription = m.goalReached },
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(t.space.s2),
    ) {
        Box(Modifier.size((t.space.s16 + t.space.s12) * rem), contentAlignment = Alignment.Center) {
            Canvas(Modifier.matchParentSize()) {
                val r = t.space.s12.toPx() * rem
                val unit = 360f / total
                val gap = 9f
                for (i in 0 until total) {
                    val isDone = i < done
                    drawArc(
                        color = if (isDone) c.text else c.borderStrong,
                        startAngle = -90f + i * unit + gap / 2f,
                        sweepAngle = unit - gap,
                        useCenter = false,
                        topLeft = Offset(center.x - r, center.y - r),
                        size = Size(2 * r, 2 * r),
                        style = Stroke(width = (if (isDone) 8.dp else 2.dp).toPx() * rem, cap = StrokeCap.Butt),
                    )
                }
            }
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                Text(sbFormatCount(done), style = ty.title.copy(fontFeatureSettings = numeric), color = c.text)
                Text(m.goalOf(sbFormatCount(total)), style = ty.caption.copy(fontFeatureSettings = numeric), color = c.textMuted)
            }
        }
        Text(caption, style = ty.caption, color = c.textMuted, textAlign = TextAlign.Center)
        // the ring's node carries „erreicht“ as its state; SbStatus's own merged node would be a second TalkBack stop
        if (reached) Box(Modifier.clearAndSetSemantics { }) { SbStatus(SbStatusTone.Success, word = m.goalReached) }
    }
}
